css:
th, td{
    border:1px solid gray;
    font-size:13px;
    line-height:1;
}
.print-format .letter-head {
  margin-bottom: 10px !important;
}
.no-border{
    border:unset;
}
.border-style{
    border: 1px solid gray; 
}
.border-top-style{
    border: 1px solid gray;
    border-top-left-radius: 10px 10px;
    border-top-right-radius: 10px 10px;
}
.border-bottom-style{
    border: 1px solid gray;
    border-bottom-left-radius: 10px 10px;
    border-bottom-right-radius: 10px 10px 
}
.border-group{
    text-align: center;
    border-bottom: 1px solid gray;
    padding-bottom: 3px;
    width:100%;
}
.font_weight{
    font-weight:600;
}
#background {
	position: absolute;
	z-index: 0;
	min-height: 143%;
	min-width: 93%;
}

#content {
	z-index: 1;
}
#bg-text {
	color: black;
	font-size: 120px;
	transform: rotate(315deg);
	-webkit-transform: rotate(315deg);
	opacity: 24%;
	text-align: center;
}
#small-bg-text {
	font-size: 20px;
}
